  # key=value line (only if inside a section, else treat with sec="")
  pos = index(line, "=")
  if (pos > 0) {
    # if no section yet, use ""
    if (cur_c == "" && nsec_c==0) cur_c = ""
    k = trim(substr(line, 1, pos-1))
    v = trim(substr(line, pos+1))
    # strip possible trailing \r already via trim
    key = cur_c SUBSEP k
    if (!(key in custom_val) && !((cur_c SUBSEP k) in custom_has)) {
      # first occurrence: record order
      custom_sec_n[cur_c]++
      custom_sec_keys[cur_c, custom_sec_n[cur_c]] = k
    }
    custom_val[key]=v
    custom_has[key]=1
  }
  next
