  # Check if defaults_has contains "" section keys not yet output
  # Simplistic: if ("" in seen_d) already handled, else if defaults_sec_n[""]>0 and "" not printed, prepend?
  # For robustness, handle orphan keys:
  if (( "" in seen_d) == 0) {
    # if there are orphan keys, output them at top
    # This case would need prepending, but unlikely; just append at top? For now append at end if not already output
    # Check if any orphan keys exist and not consumed
    orphan_out=""
    for (j=1; j<=defaults_sec_n[""]; j++) {
      k=defaults_sec_keys["", j]
      dk="" SUBSEP k
      if (!(dk in consumed)) {
        if (dk in custom_val) v=custom_val[dk]
        else v=defaults_val[dk]
        orphan_out = orphan_out k "=" v "\n"
        consumed[dk]=1
      }
    }
    for (j=1; j<=custom_sec_n[""]; j++) {
      k=custom_sec_keys["", j]
      ckkey="" SUBSEP k
      if (!(ckkey in consumed) && !(ckkey in defaults_has)) {
        orphan_out = orphan_out k "=" custom_val[ckkey] "\n"
        consumed[ckkey]=1
      }
    }
    if (orphan_out != "") {
      out = orphan_out (out != "" ? "\n" out : "")
    }
  }
  printf "%s", out
}
